WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT s.id, s.session_id, s.event_time, s.is_new_burst, s.island_id, (SELECT MAX(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS max_web_event_duration_sec FROM sessionized s ORDER BY session_id DESC
